SELECT c.client_id, c.district_id
FROM client c
WHERE EXISTS (
    SELECT 1 FROM disp d
    WHERE d.client_id = c.client_id AND d.type = 'DISPONENT'
)
AND NOT EXISTS (
    SELECT 1 FROM disp d
    WHERE d.client_id = c.client_id AND d.type = 'OWNER'
);

SELECT m.first_name || ' ' || m.last_name AS full_name, m.attr_001 AS email
FROM member m
WHERE m.position = 'Secretary';

SELECT first_name || ' ' || last_name AS full_name
FROM member
WHERE lower(trim("attr_001")) IN ('extra large', 'xl');

SELECT ROUND(100.0 * SUM(CASE WHEN mj.department = 'Business' THEN 1 ELSE 0 END) / COUNT(*), 2) AS percentage
FROM member m
LEFT JOIN major mj ON m.link_to_major = mj.major_id;

SELECT 100.0 * SUM(CASE WHEN major.major_name = 'Business' THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM member
LEFT JOIN major ON member.link_to_major = major.major_id;

SELECT ABS(
    100.0 * SUM(CASE WHEN z.short_state = 'NJ' THEN 1 ELSE 0 END) / COUNT(*)
    - 100.0 * SUM(CASE WHEN z.short_state = 'VT' THEN 1 ELSE 0 END) / COUNT(*)
) AS percentage_difference
FROM member m
LEFT JOIN zip_code z ON m.zip = z.zip_code;

SELECT CAST(SUM(CASE WHEN LOWER(TRIM(attr_001)) = 'outpatient' THEN 1 ELSE 0 END) AS REAL) / NULLIF(SUM(CASE WHEN LOWER(TRIM(attr_001)) = 'inpatient' THEN 1 ELSE 0 END), 0) AS ratio
FROM Patient
WHERE UPPER(TRIM(Diagnosis)) = 'SLE';

SELECT SUM(CASE WHEN SUBSTR(T1.attr_001, 1, 4) = '2019' THEN T2.spent ELSE 0 END) - SUM(CASE WHEN SUBSTR(T1.attr_001, 1, 4) = '2020' THEN T2.spent ELSE 0 END) AS num
FROM event AS T1
INNER JOIN budget AS T2 ON T1.event_id = T2.link_to_event;

SELECT MAX(`Percent (%) Eligible Free (K-12)`) AS highest_eligible_free_rate
FROM frpm
WHERE SUBSTR(attr_001, 1, INSTR(attr_001, CHAR(31)) - 1) = 'Alameda';

SELECT SUM(CASE WHEN SUBSTR(T1.attr_001, 1, 4) = '2019' THEN T2.spent ELSE 0 END) - SUM(CASE WHEN SUBSTR(T1.attr_001, 1, 4) = '2020' THEN T2.spent ELSE 0 END) AS num
FROM event AS T1
INNER JOIN budget AS T2 ON T1.event_id = T2.link_to_event;
